import{_ as t,o as a,c as n,a3 as o}from"./chunks/framework.I6s8z2kk.js";const p=JSON.parse('{"title":"Coding conventions","description":"","frontmatter":{},"headers":[],"relativePath":"dev/conventions/coding.md","filePath":"dev/conventions/coding.md"}'),i={name:"dev/conventions/coding.md"};function r(s,e,d,c,l,h){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="coding-conventions" tabindex="-1">Coding conventions <a class="header-anchor" href="#coding-conventions" aria-label="Permalink to &quot;Coding conventions&quot;">​</a></h1><h2 id="money-percentages-and-dates" tabindex="-1">Money, percentages and dates <a class="header-anchor" href="#money-percentages-and-dates" aria-label="Permalink to &quot;Money, percentages and dates&quot;">​</a></h2><ul><li>Amounts are <strong>integer halalas</strong> (1/100 SAR). Never floats or decimals.</li><li>Percentages are <strong>basis points</strong> (10000 = 100%), applied with <code>intdiv</code> (floor).</li><li>The app runs in <strong>UTC</strong>. Weekdays use Carbon <code>dayOfWeek</code>, where <strong>0 = Sunday</strong>. End of day in schedules is stored as <code>24:00:00</code>.</li><li>Third-party boundaries convert explicitly: Moyasar takes halalas, Tamara takes major units (divide by 100).</li></ul><h2 id="translatable-content" tabindex="-1">Translatable content <a class="header-anchor" href="#translatable-content" aria-label="Permalink to &quot;Translatable content&quot;">​</a></h2><p>Translatable fields are JSON keyed by <code>en</code> and <code>ar</code>. Every new lang file (notifications especially) needs both.</p><h2 id="php-style" tabindex="-1">PHP style <a class="header-anchor" href="#php-style" aria-label="Permalink to &quot;PHP style&quot;">​</a></h2><ul><li>Curly braces on every control structure.</li><li>Constructor property promotion; explicit return types and parameter types everywhere.</li><li>Enum cases in TitleCase.</li><li>PHPDoc over inline comments, with array shapes where useful.</li><li>Run <code>vendor/bin/pint --dirty --format agent</code> before finishing.</li></ul><h2 id="creating-files" tabindex="-1">Creating files <a class="header-anchor" href="#creating-files" aria-label="Permalink to &quot;Creating files&quot;">​</a></h2><p>Use <code>php artisan make:*</code> with <code>--no-interaction</code>, then move or adjust to the module&#39;s structure. Follow the sibling files in the same module for naming and layout.</p><h2 id="status-changes" tabindex="-1">Status changes <a class="header-anchor" href="#status-changes" aria-label="Permalink to &quot;Status changes&quot;">​</a></h2><p>Never write a status column directly:</p><table tabindex="0"><thead><tr><th>Entity</th><th>Only change it through</th></tr></thead><tbody><tr><td>Reservation</td><td><code>ReservationStateService</code></td></tr><tr><td>Purchase</td><td><code>PurchaseStateService</code></td></tr><tr><td>Payment</td><td><code>PaymentStateService</code></td></tr></tbody></table><p>Each transition locks the row, re-checks the current status, and fires its event <strong>after commit</strong>.</p><h2 id="events-and-notifications" tabindex="-1">Events and notifications <a class="header-anchor" href="#events-and-notifications" aria-label="Permalink to &quot;Events and notifications&quot;">​</a></h2><ul><li>Fire domain events inside <code>DB::afterCommit</code>.</li><li>Listeners that handle money or notifications are queued with <code>ShouldHandleEventsAfterCommit</code>.</li><li>Every notification extends <code>AppNotification</code> and is sent through <code>NotificationServiceContract</code>.</li></ul><h2 id="client-media" tabindex="-1">Client media <a class="header-anchor" href="#client-media" aria-label="Permalink to &quot;Client media&quot;">​</a></h2><p>Attach client-supplied media only through <code>TemporaryMediaService::promote()</code> or <code>promoteMany()</code>. Never pass client ids to <code>MediaService::attach()</code>.</p><h2 id="api-documentation-attributes" tabindex="-1">API documentation attributes <a class="header-anchor" href="#api-documentation-attributes" aria-label="Permalink to &quot;API documentation attributes&quot;">​</a></h2><p>Controllers and resources carry Scribe attributes (<code>#[Endpoint]</code>, <code>#[ResponseField]</code>, <code>#[ResponseFromApiResource]</code>). Update them when a response changes so the endpoint reference stays correct.</p>',19)])])}const m=t(i,[["render",r]]);export{p as __pageData,m as default};
